import os
import re
from dataclasses import dataclass
from typing import List, Dict, Any, Optional, Tuple

import requests


@dataclass
class UnsafeSpan:
    start: int
    end: int
    category: str
    severity: float


class AzureAIContentSafetyClient:
    def __init__(self, endpoint: Optional[str] = None, key: Optional[str] = None, api_version: str = "2023-10-01"):
        self.endpoint = (endpoint or os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT") or "").rstrip("/")
        self.key = key or os.getenv("AZURE_CONTENT_SAFETY_KEY") or ""
        if not self.endpoint:
            raise ValueError("AZURE_CONTENT_SAFETY_ENDPOINT is required")
        if not self.key:
            raise ValueError("AZURE_CONTENT_SAFETY_KEY is required")
        self.api_version = api_version
        self.session = requests.Session()
        self.session.headers.update(
            {
                "Ocp-Apim-Subscription-Key": self.key,
                "Content-Type": "application/json",
            }
        )

    def analyze_text(self, text: str) -> Dict[str, Any]:
        url = f"{self.endpoint}/contentsafety/text:analyze?api-version={self.api_version}"
        payload = {
            "text": text,
            "categories": ["Hate", "SelfHarm", "Sexual", "Violence"],
            "outputType": "FourSeverityLevels",
        }
        resp = self.session.post(url, json=payload, timeout=30)
        resp.raise_for_status()
        return resp.json()


def _severity_to_score(severity: Any) -> float:
    if isinstance(severity, (int, float)):
        return float(severity)
    mapping = {
        "VeryLow": 0.1,
        "Low": 0.3,
        "Medium": 0.6,
        "High": 0.9,
    }
    return mapping.get(str(severity), 0.0)


def _extract_unsafe_spans(text: str, analysis: Dict[str, Any], threshold: float = 0.6) -> List[UnsafeSpan]:
    spans: List[UnsafeSpan] = []
    categories = analysis.get("categoriesAnalysis", []) or []
    for cat in categories:
        severity = _severity_to_score(cat.get("severity"))
        if severity < threshold:
            continue
        category = str(cat.get("category", "unsafe"))
        phrases = cat.get("categorySpecificAnalysis", []) or []
        for phrase in phrases:
            phrase_text = str(phrase.get("text", "")).strip()
            if not phrase_text:
                continue
            start = phrase.get("offset")
            length = phrase.get("length")
            if isinstance(start, int) and isinstance(length, int) and start >= 0 and length > 0:
                spans.append(UnsafeSpan(start=start, end=start + length, category=category, severity=severity))
            else:
                for m in re.finditer(re.escape(phrase_text), text, flags=re.IGNORECASE):
                    spans.append(UnsafeSpan(start=m.start(), end=m.end(), category=category, severity=severity))
    spans.sort(key=lambda s: (s.start, -s.end))
    merged: List[UnsafeSpan] = []
    for span in spans:
        if not merged or span.start >= merged[-1].end:
            merged.append(span)
        else:
            prev = merged[-1]
            if span.end > prev.end or span.severity > prev.severity:
                merged[-1] = UnsafeSpan(
                    start=min(prev.start, span.start),
                    end=max(prev.end, span.end),
                    category=prev.category if prev.severity >= span.severity else span.category,
                    severity=max(prev.severity, span.severity),
                )
    return merged


def _redact_text(text: str, spans: List[UnsafeSpan], replacement: str = "[REDACTED]") -> str:
    if not spans:
        return text
    out = []
    last = 0
    for span in spans:
        out.append(text[last:span.start])
        out.append(replacement)
        last = max(last, span.end)
    out.append(text[last:])
    return "".join(out)


def flag_or_redact_unsafe_spans(
    text: str,
    redact: bool = False,
    threshold: float = 0.6,
    replacement: str = "[REDACTED]",
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
) -> Dict[str, Any]:
    client = AzureAIContentSafetyClient(endpoint=endpoint, key=key)
    analysis = client.analyze_text(text)
    spans = _extract_unsafe_spans(text, analysis, threshold=threshold)
    result: Dict[str, Any] = {
        "unsafe": bool(spans),
        "spans": [
            {
                "start": s.start,
                "end": s.end,
                "category": s.category,
                "severity": s.severity,
                "text": text[s.start:s.end],
            }
            for s in spans
        ],
        "analysis": analysis,
    }
    if redact:
        result["text"] = _redact_text(text, spans, replacement=replacement)
    return result
